255				return reject(err)
256			}
257			h.Write(ehdr)
258			flag := ehdr[0]
259			keyLen := binary.LittleEndian.Uint32(ehdr[1:5])
260			valLen := binary.LittleEndian.Uint32(ehdr[5:9])
261			seq := binary.LittleEndian.Uint64(ehdr[9:17])
262			if (flag != ckptFlagPut && flag != ckptFlagDelete) ||
263				keyLen == 0 || keyLen > maxRecord || valLen > maxRecord ||
264				(flag == ckptFlagDelete && valLen != 0) {
265				return reject(errors.New("snapshot: malformed checkpoint entry"))
266			}
