268			if _, err := io.ReadFull(r, body); err != nil {
269				return reject(err)
270			}
271			h.Write(body)
272			key := string(body[:keyLen])
273			if seen[key] {
274				return reject(errors.New("snapshot: duplicate key in checkpoint"))
275			}
276			seen[key] = true
