302	// removeStaleCheckpointTmp deletes a half-built checkpoint temp left by a
303	// crash mid-checkpoint. Its absence is not an error.
304	func removeStaleCheckpointTmp(dir string) error {
305		err := os.Remove(dir + string(os.PathSeparator) + checkpointTmpName)
306		if err != nil && !errors.Is(err, os.ErrNotExist) {
307			return err
308		}
309		return nil
310	}
311	
312	// removeRejectedCheckpoint discards a checkpoint that failed validation and
313	// forces the directory, so a rejected artifact never lingers or occupies
314	// space. The WAL alone remains a complete source of truth.
315	func removeRejectedCheckpoint(dir string) {
316		if err := os.Remove(dir + string(os.PathSeparator) + checkpointName); err != nil {
317			return
318		}
319		_ = syncDirectory(dir)
320	}
321	
322	// retireCheckpoint durably withdraws a live checkpoint before the WAL is
323	// replaced. Compaction is the only operation that rewrites wal.log, and a
324	// checkpoint's cut offset is meaningful only against the exact log it was
325	// captured against, so the unlink (and its directory force) must be durable
326	// before the replacement log is renamed into place: after a crash at any
327	// instant, a checkpoint can never be found paired with a different WAL. Its
328	// absence is normal and not an error.
329	func retireCheckpoint(dir string) error {
330		path := dir + string(os.PathSeparator) + checkpointName
331		if _, err := os.Stat(path); err != nil {
332			if errors.Is(err, os.ErrNotExist) {
333				return nil
334			}
335			return err
336		}
337		if err := os.Remove(path); err != nil {
338			return err
339		}
340		return syncDirectory(dir)
341	}
