14	
15	// dumpView returns every live key/value pair in the latest view, sorted, so
16	// two reopened directories can be compared as exact terminal state.
17	func dumpView(t *testing.T, s *Store) []KVPair {
18		t.Helper()
19		pairs, err := s.Scan(Range{}, 0)
20		if err != nil {
21			t.Fatalf("scan: %v", err)
22		}
23		sort.Slice(pairs, func(i, j int) bool { return pairs[i].Key < pairs[j].Key })
24		return pairs
25	}
