27	// exerciseStore performs a fixed mixed workload of puts, same-key rewrites,
28	// deletes and atomic batches (including same-key-last-wins cases).
29	func exerciseStore(t *testing.T, s *Store, tag string) {
30		t.Helper()
31		must := func(err error) {
32			t.Helper()
33			if err != nil {
34				t.Fatalf("%s: %v", tag, err)
35			}
36		}
37		must(s.Put("alpha", []byte("one")))
38		must(s.Put("beta", []byte("two")))
39		must(s.Put("alpha", []byte("one-v2")))
40		must(s.CommitBatch([]BatchOp{
41			{Key: "g1", Value: []byte("a")},
42			{Key: "g1", Value: []byte("b")}, // later op wins within the batch
43			{Key: "g2", Value: []byte("c")},
44			{Key: "gone", Delete: true},
45		}))
46		must(s.Put("nil-val", nil))
47		must(s.Put("empty-val", []byte{}))
48		must(s.Put("doomed", []byte("x")))
49		must(s.Delete("doomed"))
50		must(s.Delete("never-existed")) // no-op must not disturb anything
51		must(s.CommitBatch([]BatchOp{
52			{Key: "g3", Delete: true}, // absent: whole op is a no-op
53			{Key: "beta", Delete: true},
54			{Key: "beta", Value: []byte("resurrected")}, // delete-then-put wins
55		}))
56		for i := 0; i < 3; i++ {
57			if _, err := s.Snapshot(); err != nil {
58				t.Fatalf("%s snapshot: %v", tag, err)
59			}
60		}
61	}
62	
63	func checkpointExists(t *testing.T, dir string) bool {
64		t.Helper()
65		_, err := os.Stat(filepath.Join(dir, checkpointName))
66		if err == nil {
67			return true
68		}
69		if errors.Is(err, fs.ErrNotExist) {
70			return false
71		}
72		t.Fatalf("stat checkpoint: %v", err)
73		return false
74	}
