85		// Checkpoint in the middle of continued life, then commit more work that
86		// must come back purely from the WAL tail replay.
87		if err := cp.Checkpoint(); err != nil {
88			t.Fatalf("checkpoint: %v", err)
89		}
90		if !checkpointExists(t, dirCP) {
91			t.Fatal("checkpoint file not created")
92		}
