94		post := []BatchOp{
95			{Key: "tail1", Value: []byte("t1")},
96			{Key: "alpha", Value: []byte("one-v3")},
97			{Key: "g1", Value: []byte("b2"), Delete: false},
98			{Key: "g2", Delete: true},
99		}
100		if err := cp.CommitBatch(post); err != nil {
101			t.Fatal(err)
102		}
103		if err := full.CommitBatch(post); err != nil {
104			t.Fatal(err)
105		}
106		if _, err := cp.Snapshot(); err != nil {
107			t.Fatal(err)
108		}
109		if err := cp.Close(); err != nil {
110			t.Fatal(err)
111		}
112		if err := full.Close(); err != nil {
113			t.Fatal(err)
114		}
115	
116		// Checkpoint never modifies the WAL; the tail batch landed after it.
117		if got := walSize(t, dirCP); got <= walAfter {
118			t.Fatalf("wal did not grow after checkpointed commit: %d", got)
119		}
120	
121		want := []KVPair{
122			{Key: "alpha", Value: []byte("one-v3")},
123			{Key: "beta", Value: []byte("resurrected")},
124			{Key: "empty-val", Value: []byte{}},
125			{Key: "g1", Value: []byte("b2")},
126			{Key: "nil-val", Value: nil},
127			{Key: "tail1", Value: []byte("t1")},
128		}
129	
130		reopenedFull := openStore(t, dirFull)
131		reopenedCP, err := Open(dirCP)
132		if err != nil {
133			t.Fatalf("reopen with checkpoint: %v", err)
134		}
135		defer reopenedCP.Close()
