137		gotFull := dumpView(t, reopenedFull)
138		gotCP := dumpView(t, reopenedCP)
139		if len(gotCP) != len(want) {
140			t.Fatalf("checkpoint reopen has %d pairs, want %d: %+v", len(gotCP), len(want), gotCP)
141		}
142		for i := range want {
143			if gotFull[i].Key != want[i].Key || string(gotFull[i].Value) != string(want[i].Value) {
144				t.Fatalf("full replay mismatch at %d: got %q=%q want %q=%q", i, gotFull[i].Key, gotFull[i].Value, want[i].Key, want[i].Value)
145			}
146			if gotCP[i].Key != want[i].Key || string(gotCP[i].Value) != string(want[i].Value) {
147				t.Fatalf("checkpoint reopen mismatch at %d: got %q=%q want %q=%q", i, gotCP[i].Key, gotCP[i].Value, want[i].Key, want[i].Value)
148			}
149		}
