166	func TestCheckpointSeedsOnlyAndReplaysTail(t *testing.T) {
167		// Proof that reopen loads the checkpoint and replays only the tail, not
168		// the whole log: corrupt bytes that are fully covered by the checkpoint
169		// must be invisible, while a frame appended after the checkpoint is still
170		// replayed. A from-scratch replay of this WAL would lose everything.
171		dir := tempDir(t)
