183		if cut == 0 {
184			t.Fatal("expected nonempty WAL at cut")
185		}
186		if err := s.Put("tail", []byte("later")); err != nil {
187			t.Fatal(err)
188		}
189		if err := s.Close(); err != nil {
190			t.Fatal(err)
191		}
192	
193		// Garble the checkpoint-covered prefix only.
194		path := filepath.Join(dir, walName)
195		data, err := os.ReadFile(path)
196		if err != nil {
197			t.Fatal(err)
198		}
199		for i := int64(0); i < cut-1; i++ {
200			data[i] ^= 0xFF
201		}
202		if err := os.WriteFile(path, data, 0o600); err != nil {
203			t.Fatal(err)
204		}
205	
206		s2, err := Open(dir)
207		if err != nil {
208			t.Fatalf("reopen with covered-prefix corruption: %v", err)
209		}
210		defer s2.Close()
211		if got, ok, _ := s2.Get("covered1"); !ok || string(got) != "c1" {
212			t.Fatalf("checkpoint-covered value lost: %q ok=%v", got, ok)
213		}
214		if got, ok, _ := s2.Get("tail"); !ok || string(got) != "later" {
215			t.Fatalf("tail value not replayed: %q ok=%v", got, ok)
216		}
217	}
218	
219	func TestCheckpointRejectsCorruptAndFallsBack(t *testing.T) {
220		for _, tc := range []struct {
221			name string
222			// mutate transforms the valid checkpoint bytes into a bad artifact.
223			mutate func(b []byte) []byte
224		}{
225			{"truncated", func(b []byte) []byte { return b[:len(b)/2] }},
226			{"bad magic", func(b []byte) []byte { b[0] ^= 0xFF; return b }},
227			{"bad version", func(b []byte) []byte {
228				b[7] = 99 // version field's high byte flip => unknown version
229				return b
230			}},
231			{"flipped payload byte", func(b []byte) []byte {
232				b[len(b)-10] ^= 0x01 // breaks the CRC check
233				return b
234			}},
235			{"trailing bytes", func(b []byte) []byte { return append(b, 0xAA) }},
236		} {
237			t.Run(tc.name, func(t *testing.T) {
238				dir := tempDir(t)
239				s := openStore(t, dir)
240				if err := s.Put("keep", []byte("value")); err != nil {
241					t.Fatal(err)
242				}
