697	func TestCheckpointConcurrentWithEverything(t *testing.T) {
698		dir := tempDir(t)
699		s := openStore(t, dir)
700	
701		const writers = 4
702		const rounds = 80
703		var wg sync.WaitGroup
704		for w := 0; w < writers; w++ {
705			wg.Add(1)
706			go func(w int) {
707				defer wg.Done()
708				for i := 0; i < rounds; i++ {
709					key := fmt.Sprintf("k%d", w)
710					if err := s.CommitBatch([]BatchOp{
711						{Key: key, Value: []byte(fmt.Sprintf("%d-%d", w, i))},
712						{Key: "shared", Value: []byte(fmt.Sprintf("%d", i))},
713					}); err != nil {
714						t.Errorf("batch: %v", err)
715						return
716					}
717					if i%13 == 0 {
718						if err := s.Delete(key); err != nil {
719							t.Errorf("delete: %v", err)
720							return
721						}
722					}
723				}
724			}(w)
725		}
726		for c := 0; c < 2; c++ {
727			wg.Add(1)
728			go func() {
729				defer wg.Done()
730				for i := 0; i < 25; i++ {
731					if err := s.Checkpoint(); err != nil {
732						if errors.Is(err, fs.ErrClosed) {
733							return
734						}
735						t.Errorf("checkpoint: %v", err)
736						return
737					}
738				}
739			}()
740		}
741		wg.Add(1)
742		go func() {
743			defer wg.Done()
744			for i := 0; i < 15; i++ {
745				if err := s.Compact(); err != nil {
746					if errors.Is(err, fs.ErrClosed) {
747						return
748					}
749					t.Errorf("compact: %v", err)
750					return
751				}
752			}
753		}()
754		stop := make(chan struct{})
755		var readers sync.WaitGroup
756		readers.Add(1)
757		go func() {
758			defer readers.Done()
759			for {
760				select {
761				case <-stop:
762					return
763				default:
764				}
765				v, err := s.Snapshot()
766				if err != nil {
767					if errors.Is(err, fs.ErrClosed) {
768						return
769					}
770					t.Errorf("snapshot: %v", err)
771					return
772				}
773				got, _ := v.Get("shared")
774				if again, ok := v.Get("shared"); ok && string(again) != string(got) {
775					t.Errorf("fixed snapshot view changed: %q vs %q", again, got)
776				}
777				cur, err := v.OpenCursorPrefix("k")
778				if err == nil {
779					if _, perr := cur.Page(0, 64); perr != nil {
780						t.Errorf("cursor page: %v", perr)
781					}
782					cur.Close()
783				}
784				v.Close()
785			}
786		}()
787	
788		wg.Wait()
789		close(stop)
790		readers.Wait()
791	
792		// Whatever the interleaving, a final checkpoint captures complete state
793		// and a reopen reproduces it exactly whether it loads the checkpoint or
794		// retires it after a last compaction.
795		if err := s.Checkpoint(); err != nil {
796			t.Fatalf("final checkpoint: %v", err)
797		}
798		live := dumpView(t, s)
799		if err := s.Close(); err != nil {
800			t.Fatal(err)
801		}
802		s2, err := Open(dir)
803		if err != nil {
804			t.Fatalf("reopen: %v", err)
805		}
806		defer s2.Close()
807		reopened := dumpView(t, s2)
808		if len(reopened) != len(live) {
809			t.Fatalf("reopened has %d pairs, live had %d", len(reopened), len(live))
810		}
811		for i := range live {
812			if reopened[i].Key != live[i].Key || string(reopened[i].Value) != string(live[i].Value) {
813				t.Fatalf("mismatch at %d: %q=%q vs %q=%q", i,
814					reopened[i].Key, reopened[i].Value, live[i].Key, live[i].Value)
815			}
816		}
817	}
