// planSegmentedWAL partitions retained frames at the window layers' sequence
// watermarks and derives, for each surviving layer, the entries that layering
// its files must carry so that "seed layers 0..j, replay frames after cut j"
// reconstructs the identical terminal state a full replay does.
//
// windowLayers are the surviving (in-window) layers oldest first; only their
// sequence watermarks and snapshot counts are used, because the rebuilt
// entries are derived from the retained frame set itself, which is the only
// history the new WAL preserves. Frames a compaction sheds (e.g. an
// unsheilded tombstone) appear in no layer: a layer never promises state the
// post-compaction log cannot finish reconstructing.
func planSegmentedWAL(plan *compactionPlan, windowLayers []layerState) *segmentedWAL {
	n := len(windowLayers)
	watermarks := make([]uint64, n)
	snaps := make([]uint64, n)
	for i, l := range windowLayers {
		watermarks[i] = l.seq
		snaps[i] = l.snaps
	}

	segments := make([][]keyHistory, n+1)
	// Latest retained version of each key not after each watermark.
	terminalAt := make([]map[string]nodeVer, n)
	for i := range terminalAt {
		terminalAt[i] = make(map[string]nodeVer)
	}
	// Keys carrying at least one frame in segment j (j<n), i.e. changed
	// between watermark j-1 and j; those are exactly layer j's delta keys.
	changedIn := make([]map[string]struct{}, n)
	for i := range changedIn {
		changedIn[i] = make(map[string]struct{})
	}
	tailKeySet := make(map[string]struct{})

	for _, k := range plan.keys {
		buckets := make([][]nodeVer, n+1)
		for _, ver := range plan.hist[k] {
			j := segmentFor(ver.seq, watermarks)
			buckets[j] = append(buckets[j], ver)
			if j < n {
				// Frames within one key are ascending, so the last frame at or
				// before watermark j seen while scanning buckets 0..j is its
				// terminal there.
				terminalAt[j][k] = ver
				changedIn[j][k] = struct{}{}
			} else {
				tailKeySet[k] = struct{}{}
			}
		}
		for j := range buckets {
			if len(buckets[j]) > 0 {
				segments[j] = append(segments[j], keyHistory{key: k, versions: buckets[j]})
			}
		}
	}
	// terminalAt[j] must reflect the newest frame <= watermark j across ALL
	// earlier segments, not just segment j: propagate.
	for j := 1; j < n; j++ {
		for k, v := range terminalAt[j-1] {
			if _, ok := terminalAt[j][k]; !ok {
				terminalAt[j][k] = v
			}
		}
	}
	// A key may have a frame <= watermark j but none in segment j (its frame
	// landed earlier); propagation above covers the terminal, while delta
	// membership must track actual segment-j frames only — changedIn already
	// does. Segment key lists stay sorted for deterministic output.
	for j := range segments {
		sort.Slice(segments[j], func(a, b int) bool { return segments[j][a].key < segments[j][b].key })
	}

	layers := make([]rebuiltLayer, n)
	for j := 0; j < n; j++ {
		var entries []checkpointEntry
		if j == 0 {
			// Full base: terminal state of every key at or before watermark 0.
			keys := make([]string, 0, len(terminalAt[0]))
			for k := range terminalAt[0] {
				keys = append(keys, k)
			}
			sort.Strings(keys)
			entries = make([]checkpointEntry, 0, len(keys))
			for _, k := range keys {
				entries = append(entries, entryFromVer(k, terminalAt[0][k]))
			}
		} else {
			// Delta: exactly the keys with a frame in segment j, carrying
			// their terminal state at watermark j.
			keys := make([]string, 0, len(changedIn[j]))
			for k := range changedIn[j] {
				keys = append(keys, k)
			}
			sort.Strings(keys)
			entries = make([]checkpointEntry, 0, len(keys))
			for _, k := range keys {
				entries = append(entries, entryFromVer(k, terminalAt[j][k]))
			}
		}
		layers[j] = rebuiltLayer{entries: entries, seq: watermarks[j], snaps: snaps[j]}
	}

	tailKeys := make([]string, 0, len(tailKeySet))
	for k := range tailKeySet {
		tailKeys = append(tailKeys, k)
	}
	sort.Strings(tailKeys)
	return &segmentedWAL{segments: segments, layers: layers, tailKeys: tailKeys}
