// per currently present key; deleted keys drop out, as in the baseline.
func (p *compactionPlan) freshView() *view {
	v := newView(nil)
	for _, k := range p.keys {
		versions := p.hist[k]
		head := versions[len(versions)-1]
		if head.present {
