// state from v. Absent keys are skipped: a delta never carries a "never
// existed" entry. Output is sorted by key.
func captureDelta(v *view, changes []batchChange) []checkpointEntry {
	if len(changes) == 0 {
		return nil
	}
	seen := make(map[string]struct{}, len(changes))
	keys := make([]string, 0, len(changes))
	for i := range changes {
		k := changes[i].key
		if _, dup := seen[k]; dup {
			continue
		}
		seen[k] = struct{}{}
		keys = append(keys, k)
	}
	entries := make([]checkpointEntry, 0, len(keys))
	sort.Strings(keys)
	for _, k := range keys {
		n := v.lookup(k)
		if n == nil {
			continue
		}
		e := checkpointEntry{key: k, present: n.present, seq: n.seq}
		if n.present {
			e.value = cloneBytes(n.value)
		}
		entries = append(entries, e)
	}
	return entries
}

