// writeLayerFile serializes layer to relName freshly (O_EXCL), forces the
// whole file with one fsync and closes it. It never touches a live layer; the
// caller renames it into place only once this succeeds.
func writeLayerFile(dir, relName string, layer capturedLayer) (err error) {
	path := filepath.Join(dir, relName)
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return err
	}
	defer func() {
		if err != nil {
			f.Close()
			os.Remove(path)
		}
	}()

