package snapshot

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"testing"
)

// fullReplayView opens dir after removing the whole checkpoint chain, forcing
// a pure WAL replay, and dumps the resulting state.
func fullReplayView(t *testing.T, dir string) []KVPair {
	t.Helper()
	os.RemoveAll(filepath.Join(dir, checkpointDirName))
	os.Remove(filepath.Join(dir, checkpointName))
	s, err := Open(dir)
	if err != nil {
		t.Fatalf("full replay open: %v", err)
	}
	defer s.Close()
	return dumpView(t, s)
}

func TestScratchLayeredChainEquivalence(t *testing.T) {
	dir := tempDir(t)
	s := openStore(t, dir)

	want := map[string]string{}
	put := func(k, v string) {
		if err := s.Put(k, []byte(v)); err != nil {
			t.Fatal(err)
		}
