// captureView serializes the terminal state of a view. Entries are sorted by
// key for a canonical encoding and values are copied so later commits cannot
// mutate the bytes being written.
func captureView(v *view) []checkpointEntry {
	entries := make([]checkpointEntry, 0, v.count())
	v.rangeEach(func(k string, n *node) bool {
		e := checkpointEntry{key: k, present: n.present, seq: n.seq}
		if n.present {
			e.value = cloneBytes(n.value)
		}
		entries = append(entries, e)
		return true
	})
	sort.Slice(entries, func(i, j int) bool { return entries[i].key < entries[j].key })
	return entries
}

